import{i as e,r as t,s as n,t as r}from"./app-D1trhGny.js";var i=JSON.parse(`{"path":"/web3/smart/kusama/","title":"Kusama(KSM)","lang":"zh-CN","frontmatter":{"description":"Kusama(KSM) Kusama 是 Polkadot 的“金丝雀网络”，是一个实验性的区块链平台，旨在为开发者和项目提供一个快速迭代和测试创新的平台。Kusama 由 Web3 基金会支持，旨在成为 Polkadot 生态系统中的一个重要组成部分。以下是 Kusama 的发展历程： 2019 年 项目启动：2019 年，Kusama 作为 Pol...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Kusama(KSM)\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-03-11T05:49:26.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/web3/smart/kusama/"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"Kusama(KSM)"}],["meta",{"property":"og:description","content":"Kusama(KSM) Kusama 是 Polkadot 的“金丝雀网络”，是一个实验性的区块链平台，旨在为开发者和项目提供一个快速迭代和测试创新的平台。Kusama 由 Web3 基金会支持，旨在成为 Polkadot 生态系统中的一个重要组成部分。以下是 Kusama 的发展历程： 2019 年 项目启动：2019 年，Kusama 作为 Pol..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-03-11T05:49:26.000Z"}],["meta",{"property":"article:modified_time","content":"2026-03-11T05:49:26.000Z"}]]},"git":{"createdTime":1734955114000,"updatedTime":1773208166000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@gmail.com","commits":2,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":1.63,"words":489},"filePathRelative":"web3/smart/kusama/README.md","autoDesc":true}`),a={name:`README.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="kusama-ksm" tabindex="-1"><a class="header-anchor" href="#kusama-ksm"><span>Kusama(KSM)</span></a></h1><p><a href="https://kusama.network/" target="_blank" rel="noopener noreferrer">Kusama</a> 是 Polkadot 的“金丝雀网络”，是一个实验性的区块链平台，旨在为开发者和项目提供一个快速迭代和测试创新的平台。Kusama 由 Web3 基金会支持，旨在成为 Polkadot 生态系统中的一个重要组成部分。以下是 Kusama 的发展历程：</p><h2 id="_2019-年" tabindex="-1"><a class="header-anchor" href="#_2019-年"><span>2019 年</span></a></h2><ul><li><strong>项目启动</strong>：2019 年，Kusama 作为 Polkadot 的先行网络启动，旨在为即将到来的 Polkadot 网络提供一个实验性平台。它允许开发者在一个实际环境中测试新技术和协议。</li><li><strong>Kusama 主网发布</strong>：2019 年 8 月，Kusama 主网正式上线，标志着 Kusama 网络的诞生。它采用了与 Polkadot 相同的代码库，但在治理和升级方面更加灵活。</li></ul><h2 id="_2020-年" tabindex="-1"><a class="header-anchor" href="#_2020-年"><span>2020 年</span></a></h2><ul><li><strong>网络稳定</strong>：在 2020 年，Kusama 网络逐渐稳定，更多的项目和开发者开始在 Kusama 上进行实验和部署。Kusama 的治理机制使得网络能够快速进行升级和改进。</li><li><strong>首批平行链插槽拍卖</strong>：2020 年，Kusama 开始进行首批平行链插槽拍卖。平行链是 Kusama 和 Polkadot 的关键组件，允许多个区块链并行运行，并与中继链进行互操作。</li></ul><h2 id="_2021-年" tabindex="-1"><a class="header-anchor" href="#_2021-年"><span>2021 年</span></a></h2><ul><li><strong>平行链启动</strong>：2021 年，Kusama 成功启动了首批平行链，项目如 Karura、Moonriver 和 Shiden 等成功获得了插槽，并开始在 Kusama 网络上运行。</li><li><strong>跨链消息传递</strong>：Kusama 开始实现跨链消息传递功能，使得不同的平行链能够互相通信和交互，进一步增强了网络的互操作性。</li></ul><h2 id="_2022-年" tabindex="-1"><a class="header-anchor" href="#_2022-年"><span>2022 年</span></a></h2><ul><li><strong>生态系统扩展</strong>：随着更多平行链的上线，Kusama 生态系统迅速扩展，涵盖 DeFi、NFT、去中心化治理和更多领域的应用。</li><li><strong>网络升级</strong>：Kusama 持续进行网络升级，以引入新功能和改进现有功能，确保网络的性能和安全性。</li></ul>`,10)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};